do $$ declare r record; begin for r in select p.oid,n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) args from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('business_event_analytics','business_event_detail','business_promotion_analytics','business_promotion_detail','business_qr_analytics','business_qr_detail','business_qr_authorized','business_list_contests','business_list_events','list_qr_engagement_programs','promotion_redemption_summary','promotion_redemption_rewards_summary') loop execute format('revoke execute on function %I.%I(%s) from anon',r.nspname,r.proname,r.args); execute format('grant execute on function %I.%I(%s) to authenticated',r.nspname,r.proname,r.args); end loop; end $$;
